export function getBearagnosticReleaseCopy(locale: LocaleCode): BearagnosticReleaseCopy {
  const base = copy[locale] ?? en;
  const extraFaq = operationalFaq[locale] ?? operationalFaq.en;
  const install = installFaq[locale] ?? installFaq.en;
  return { ...base, faqItems: [...base.faqItems, ...extraFaq, install] };
}
